// Called by the API workflows and "Date Check & Status Updates" with an
// event and ids only. Everything a message needs is read here, after the
// caller's writes, so the counts already include the change that triggered the event.
const input = $("When called").first().json;
const event = input.event;
const pitchId = input.pitchId || "";
const workationId = input.workationId || "";
const actorSub = input.actorSub || "";
const promoteSub = input.promoteSub || "";
const site = $vars.SITE_URL;

const rows = (node) => $(node).all().map((i) => i.json);
const profiles = new Map(
  rows("Get profiles").filter((r) => r.user_sub).map((r) => [r.user_sub, r]),
);
const pitch = pitchId ? rows("Get pitches").find((r) => r.pitch_id === pitchId) : undefined;
const trip = workationId
  ? rows("Get workations").find((r) => r.workation_id === workationId)
  : undefined;
const interested = new Set(
  rows("Get interest").filter((r) => r.pitch_id === pitchId).map((r) => r.user_sub),
).size;
const signups = rows("Get signups")
  .filter((r) => r.workation_id === workationId)
  .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt));
const going = signups.filter((r) => r.status === "going");
const waitlist = signups.filter((r) => r.status === "waitlist");

// Slack reads &, < and > as markup, so escape anything a colleague typed.
const esc = (value) =>
  String(value ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const quote = (value) => `> ${esc(value).replace(/\n/g, "\n> ")}`;
const nameOf = (sub) => esc(profiles.get(sub)?.name || "Someone");
const organizerOf = (row) =>
  profiles.get(row.organizer)?.name ? nameOf(row.organizer) : "The organizer";
const emailOf = (sub) => profiles.get(sub)?.email || "";
// Dates are YYYY-MM-DD String columns. American English, like the site.
const day = (iso) => DateTime.fromISO(String(iso)).toFormat("LLL d, yyyy");
const dates = (row) => `${day(row.start_date)} to ${day(row.end_date)}`;
const link = (path, text) => `<${site}${path}|${text}>`;
// People in a message are written as placeholders, which "Address messages"
// fills in once their Slack accounts are looked up: an @-mention in channel
// posts, and in DMs to organizers a link that opens a DM with the person.
// Both fall back to the plain name. `names` holds those names by email.
const names = {};
const tag = (kind, sub) => {
  const email = emailOf(sub);
  if (!email) return nameOf(sub);
  names[email] = nameOf(sub);
  return `{${kind}:${email}}`;
};
const mention = (sub) => tag("mention", sub);
const dmLink = (sub) => tag("dm", sub);
// "1 person", "2 people": counts go into sentences.
const people = (n) => (n === 1 ? "1 person" : `${n} people`);

const messages = [];
const dm = (sub, text) => {
  if (sub && emailOf(sub)) messages.push({ target: "dm", lookupEmail: emailOf(sub), text });
};
// Only pitches the bot announced have a thread. Older ones get no replies.
// Trip events pass the trip's pitch as `row`, since they have no pitchId.
const reply = (text, broadcast = false, row = pitch) => {
  if (row?.slack_ts) {
    messages.push({
      target: "thread",
      lookupEmail: "",
      threadTs: String(row.slack_ts),
      broadcast,
      text,
    });
  }
};

// The channel post that opens a pitch's thread. Also used to edit that post
// when the pitch changes, so the top of the thread always shows its details.
// It links to the pitch's own page on the site, /pitches/<pitch_id>.
const announcement = (row) =>
  `*New pitch: ${esc(row.place)}*\n` +
  `${dates(row)}. ${mention(row.organizer)} is pitching it. It goes ahead with ` +
  `${row.threshold} interested people by ${day(row.deadline)}.\n` +
  (row.description ? `${quote(row.description)}\n` : "") +
  `${link(`/pitches/${encodeURIComponent(row.pitch_id)}`, "See the pitch and register interest")}. ` +
  "Questions or ideas? Reply in this thread.";

if (event === "pitch_created" && pitch) {
  messages.push({
    target: "channel",
    lookupEmail: "",
    text: announcement(pitch),
  });
}

// An edit by the organizer: the post is rewritten with the current details,
// and a reply in the thread lists what changed. A save that changed nothing
// sends nothing.
if (event === "pitch_updated" && pitch?.slack_ts) {
  // The pitch as it was before the edit, sent by /pitch-update.
  let before = {};
  try {
    before = JSON.parse(input.before || "{}");
  } catch {
    before = {};
  }
  const same = (key) => String(before[key] ?? "") === String(pitch[key] ?? "");
  const size = (row) => (typeof row.capacity === "number" ? `up to ${row.capacity}` : "no limit");
  const cost = (row) =>
    typeof row.cost_estimate === "number" ? `€${row.cost_estimate} per person` : "not estimated";
  const changes = [];
  if (!same("place")) changes.push(`Place: ${esc(before.place)} → ${esc(pitch.place)}`);
  if (!same("start_date") || !same("end_date")) {
    changes.push(`Dates: ${dates(before)} → ${dates(pitch)}`);
  }
  if (!same("deadline")) changes.push(`Deadline: ${day(before.deadline)} → ${day(pitch.deadline)}`);
  if (!same("threshold")) changes.push(`Interest needed: ${before.threshold} → ${pitch.threshold}`);
  if (!same("capacity")) changes.push(`Group size: ${size(before)} → ${size(pitch)}`);
  if (!same("cost_estimate")) changes.push(`Cost: ${cost(before)} → ${cost(pitch)}`);
  if (!same("cost_includes")) {
    changes.push(
      pitch.cost_includes
        ? `The cost now covers: ${esc(pitch.cost_includes)}`
        : "The cost no longer says what it covers",
    );
  }
  if (!same("accommodation_url")) {
    changes.push(
      pitch.accommodation_url
        ? `New accommodation link: <${esc(pitch.accommodation_url)}|See the place>`
        : "Accommodation link removed",
    );
  }
  if (!same("image_url")) changes.push(pitch.image_url ? "New photo on the pitch" : "Photo removed");
  if (!same("description")) changes.push(`New description:\n${quote(pitch.description)}`);
  if (changes.length) {
    messages.push({
      target: "update",
      ts: String(pitch.slack_ts),
      lookupEmail: "",
      text: announcement(pitch),
    });
    // Saving an expired pitch reopens it, so the thread's "won't go ahead"
    // no longer holds. Also sent to the channel, like a new pitch.
    const reopened = before.status === "expired" && pitch.status === "open";
    const list = changes.map((c) => `• ${c}`).join("\n");
    if (reopened) {
      reply(
        `${organizerOf(pitch)} reopened this pitch. Interest counts until ${day(pitch.deadline)}:\n${list}`,
        true,
      );
    } else {
      reply(`${organizerOf(pitch)} updated this pitch:\n${list}`);
    }
  }
}

if (
  (event === "interest_added" || event === "interest_removed") &&
  pitch &&
  actorSub !== pitch.organizer
) {
  const tally = `${interested} of ${pitch.threshold} interested so far.`;
  if (event === "interest_added") {
    const enough =
      interested >= pitch.threshold
        ? " Yay! 🥳 You've reached the minimum required people! Get ready to organize the next n8ncation!"
        : "";
    dm(
      pitch.organizer,
      `${dmLink(actorSub)} is interested in your pitch for ${esc(pitch.place)}. ${tally}${enough}`,
    );
  } else {
    dm(
      pitch.organizer,
      `${dmLink(actorSub)} is no longer interested in your pitch for ${esc(pitch.place)}. ${tally}`,
    );
  }
}

if (event === "pitch_cancelled" && pitch) {
  reply(`${organizerOf(pitch)} cancelled this pitch:\n${quote(pitch.cancel_reason)}`);
}

if (event === "pitch_expired" && pitch) {
  reply(
    `The deadline passed with ${interested} of ${pitch.threshold} interested, ` +
      `so this trip won't go ahead. Have another idea? ${link("/pitch", "Pitch a trip")}.`,
  );
}

if (event === "pitch_confirmed" && pitch && trip) {
  const tripLink = link(`/n8ncation/${trip.slug}`, `See ${esc(trip.title)}`);
  // Everyone going except the organizer, each linked so a DM is one click.
  const others = going
    .filter((r) => r.user_sub !== trip.organizer)
    .map((r) => dmLink(r.user_sub))
    .join(", ");
  const waiting = waitlist.length
    ? ` ${waitlist.length} more ${waitlist.length === 1 ? "is" : "are"} on the waitlist.`
    : "";
  // In the pitch's thread and, with "Also send to channel", in the channel.
  reply(
    `*${esc(trip.place)} is happening* as ${esc(trip.title)}, ${dates(trip)}.\n` +
      `${people(going.length)} ${going.length === 1 ? "has" : "have"} a spot.${waiting} A spot is confirmed once the ` +
      "deposit is paid. If a deposit doesn't come in, the next person on the " +
      `waitlist moves up.\n${tripLink}`,
    true,
  );
  dm(
    trip.organizer,
    `Your pitch for ${esc(trip.place)} reached its target and is now ${esc(trip.title)}. Next steps:\n` +
      (others ? `• Ask everyone going for their deposit: ${others}\n` : "") +
      "• Book the accommodation once the deposits are in\n" +
      `• Check everyone's logistics and the waitlist on the trip page\n${tripLink}`,
  );
  for (const row of going) {
    if (row.user_sub !== trip.organizer) {
      dm(
        row.user_sub,
        `${esc(trip.place)} is happening, and you have a spot on ${esc(trip.title)}, ` +
          `${dates(trip)}. ${organizerOf(trip)} will ask you for a deposit to confirm it.\n${tripLink}`,
      );
    }
  }
  waitlist.forEach((row, index) =>
    dm(
      row.user_sub,
      `${esc(trip.place)} is happening as ${esc(trip.title)}, ${dates(trip)}. It's full, ` +
        `so you're number ${index + 1} on the waitlist. If a spot opens up, you move up ` +
        `automatically and get a message here.\n${tripLink}`,
    ),
  );
}

// The trip's photo folder, created by "Trip Drive Folders" on the morning
// the trip starts. Announced in the thread of the pitch the trip came from;
// a trip made by hand, or pitched before the bot, has no thread.
if (event === "photos_folder_created" && trip?.drive_folder_url) {
  const tripPitch = rows("Get pitches").find((r) => r.workation_id === workationId);
  reply(
    `*The photo folder for ${esc(trip.title)} is open.* Everyone going can add their ` +
      `photos and videos from ${esc(trip.place)}: <${trip.drive_folder_url}|Open the shared folder>. ` +
      "Drive emails each of you an invite. After the trip, everyone at n8n.io can view the " +
      `folder, and the photos show on the trip page.\n` +
      link(`/n8ncation/${trip.slug}`, `See ${esc(trip.title)}`),
    false,
    tripPitch,
  );
}

if (event === "rsvp_added" && trip && actorSub !== trip.organizer) {
  const mine = signups.find((r) => r.user_sub === actorSub);
  const tripLink = link(`/n8ncation/${trip.slug}`, "See the attendee list");
  if (mine?.status === "going") {
    dm(
      trip.organizer,
      `${dmLink(actorSub)} signed up for ${esc(trip.title)} in ${esc(trip.place)}. ` +
        `Ask them for their deposit to confirm their spot.\n${tripLink}`,
    );
  } else if (mine?.status === "waitlist") {
    dm(
      trip.organizer,
      `${dmLink(actorSub)} joined the waitlist for ${esc(trip.title)} in ${esc(trip.place)} ` +
        `at number ${waitlist.indexOf(mine) + 1}.\n${tripLink}`,
    );
  }
}

if (event === "rsvp_cancelled" && trip) {
  const tripLink = link(`/n8ncation/${trip.slug}`, `See ${esc(trip.title)}`);
  if (actorSub !== trip.organizer) {
    const moved =
      promoteSub && promoteSub !== trip.organizer
        ? ` ${dmLink(promoteSub)} moved up from the waitlist and has the spot now. Ask them for their deposit.`
        : "";
    dm(
      trip.organizer,
      `${dmLink(actorSub)} cancelled their RSVP for ${esc(trip.title)} in ${esc(trip.place)}.${moved}\n${tripLink}`,
    );
  }
  if (promoteSub) {
    dm(
      promoteSub,
      `A spot opened up on ${esc(trip.title)} in ${esc(trip.place)}, ${dates(trip)}, and ` +
        `you've moved up from the waitlist: you're going. ${organizerOf(trip)} will ask ` +
        `you for a deposit to confirm it.\n${tripLink}`,
    );
  }
}

return messages.map((json) => ({ json: { ...json, names } }));

// Fills in the people in each message. "Lookup Slack user" keeps the order of
// "People to look up" (a failed lookup still outputs an item). A DM to
// someone without a Slack account is dropped, and a person who can't be
// found is shown by name. A DM link uses Slack's slack://user deep link,
// which opens a DM with that person in the Slack apps.
const emails = $("People to look up").all().map((i) => i.json.email);
const accounts = new Map();
$input.all().forEach((item, index) => {
  if (item.json.id) accounts.set(emails[index], { id: item.json.id, team: item.json.team_id });
});
return $("Build messages")
  .all()
  .flatMap((item) => {
    const message = item.json;
    const text = String(message.text).replace(
      /\{(mention|dm):([^}]+)\}/g,
      (placeholder, kind, email) => {
        const account = accounts.get(email);
        const name = message.names?.[email] ?? email;
        if (!account) return name;
        return kind === "mention"
          ? `<@${account.id}>`
          : `<slack://user?team=${account.team}&id=${account.id}|${name}>`;
      },
    );
    if (message.target === "dm") {
      const account = accounts.get(message.lookupEmail);
      return account ? [{ json: { ...message, text, slackUserId: account.id } }] : [];
    }
    return [{ json: { ...message, text } }];
  });

// Everyone the messages go to or name, once each, for "Lookup Slack user".
// With nobody to look up (a thread reply that names no one), one empty item
// keeps the run going; its lookup fails quietly.
const emails = new Set();
for (const { json } of $input.all()) {
  if (json.lookupEmail) emails.add(json.lookupEmail);
  for (const match of String(json.text).matchAll(/\{(?:mention|dm):([^}]+)\}/g)) {
    emails.add(match[1]);
  }
}
return emails.size
  ? [...emails].map((email) => ({ json: { email } }))
  : [{ json: { email: "" } }];
